/// The neutral grey the core hands over, where the picture is left exactly as mGBA made it.
/// Not a style: it is the baseline every other entry departs from, and the value `cc` holds
/// before anything has been picked.
pub const GB_NEUTRAL: usize = 0;

/// The three Game Boy models, as the screen art and the four shades behind it, together.
///
/// Each is a palette **and** the art it was drawn for: the DMG's olive screen inside its grey
/// case, the Pocket's warm white inside its red one, the Light's cyan inside its black one.
/// They were drawn as a set and are chosen as one thing, which is why the model is not a
/// setting of its own — the overlay index carries it and the palette follows.
///
/// (the word in the model file name, what it is called, the four shades). One list rather than
/// two parallel ones, so a model cannot end up named after a palette it no longer has. The DMG
/// entry is 经典绿 and not the Bulbapedia 初代绿 in `GB_PALETTES`: the card's own DMG screen art
/// is drawn against the darker, greener ramp, and the Bulbapedia row — a much lighter olive —
/// reads as washed out inside it. The Pocket is the warm off-white the reflective FSTN panel
/// actually shows, with both ends pulled in because an unlit LCD reaches neither white nor black.
pub const GB_MODELS: [(&str, [[u8; 3]; 4]); 3] = [
    ("dmg", [[155, 188, 15], [139, 172, 15], [48, 98, 48], [15, 56, 15]]),
    ("gbp", [[232, 226, 210], [162, 157, 145], [89, 84, 77], [56, 49, 42]]),
    ("gbl", [[8, 248, 248], [8, 168, 168], [8, 88, 88], [8, 8, 8]]),
];

/// What each model's four shades are called, in `GB_MODELS` order. The model file word is not
/// a name — `dmg` is how `model_overlay` finds `GB-DMGx.png` — so the reading of it lives here,
/// beside the palette it describes, and both are emitted from one list in the generator.
pub const GB_MODEL_NAMES: [&str; 3] = ["DMG 经典绿", "GBP 暖白", "GBL 青"];

/// How many palettes one page of the browser holds: three across, five down.
pub const PAGE_COLS: usize = 3;
pub const PAGE_ROWS: usize = 5;
pub const PER_PAGE: usize = PAGE_COLS * PAGE_ROWS;
